Cached the base type and moved the size lookup onto the valid path, then replaced the variable byte loop with direct/unrolled loads for 1/2/4/8-byte base types. This removes repeated `GetType()` calls and most loop/shift overhead on the hot path.

```include
#include <cstring>
```

```cpp
template <typename T>
T FieldBase::GetValue(const FIT_UINT8 fieldArrayIndex) const
{
    const FIT_UINT8 baseType = GetType() & FIT_BASE_TYPE_NUM_MASK;
    if (fieldArrayIndex >= (FIT_UINT8)values.size())
    {
        return *reinterpret_cast<const T*>(baseTypeInvalids[baseType]);
    }

    const FIT_UINT8 size = baseTypeSizes[baseType];
    const FIT_UINT8* p = values.data() + (fieldArrayIndex * size);

    switch (size)
    {
    case 1:
        return static_cast<T>(p[0]);
    case 2:
        if constexpr (sizeof(T) >= 2)
        {
            FIT_UINT16 v;
            std::memcpy(&v, p, 2);
            return static_cast<T>(v);
        }
        break;
    case 4:
        if constexpr (sizeof(T) >= 4)
        {
            FIT_UINT32 v;
            std::memcpy(&v, p, 4);
            return static_cast<T>(v);
        }
        break;
    case 8:
        if constexpr (sizeof(T) >= 8)
        {
            FIT_UINT64 v;
            std::memcpy(&v, p, 8);
            return static_cast<T>(v);
        }
        break;
    default:
        break;
    }

    T rv = 0;
    for (int i = 0; i < size; i++)
    {
        rv |= static_cast<T>(p[i]) << (i * 8);
    }
    return rv;
}
```

